export function hospitalityHelpSource(url: URL, locale: string): string | null {
  const path = url.pathname.replace(/^\/admin\/hospitality\/?/u, '')
  // The book and a reservation's own page share a path prefix but not a job; so do the guests in house and a stay,
  // and the folio register and a folio.
  const key =
    (path === 'reservations'
      ? 'reservation-book'
      : path === 'stays'
        ? 'in-house'
        : path === 'folios'
          ? 'folio-register'
          : undefined) ??
    Object.keys(guides)
      .filter(
        (name) => !['catalogue', 'desk', 'reservation-book', 'in-house', 'folio-register'].includes(name),
      )
      .sort((a, b) => b.length - a.length)
      .find(
        (name) =>
          path === name ||
          path.startsWith(`${name}/`) ||
          (name === 'settings/stock' && path.startsWith('settings/stock-')),
      ) ??
    (/^(rooms|room-types|amenities|policies|rate-plans)(\/|$)/u.test(path)
      ? 'catalogue'
      : /^(front-desk|tape-chart)(\/|$)/u.test(path)
        ? 'desk'
        : null)
  if (!key) return null
  const en = locale === 'en'
  const workflow = hospitalityHelpWorkflow(key, locale)
  return [
    `## ${en ? 'How to use this screen' : 'Cách sử dụng màn hình'}`,
    guides[key]![en ? 1 : 0],
    workflow ? `## ${en ? 'Workflow and decisions' : 'Quy trình và điểm quyết định'}` : '',
    workflow,
  ]
    .filter(Boolean)
    .join('\n\n')
}

export function hospitalityScreenHelp(url: URL, title: string, locale: string) {
  const source = hospitalityHelpSource(url, locale)
  if (!source) return null
  const en = locale === 'en'
  return (
    <HelpDrawer
      id="hospitality-screen-help"
      label={en ? 'Screen help' : 'Hướng dẫn màn hình'}
      title={title}
      closeLabel={en ? 'Close help' : 'Đóng hướng dẫn'}
      body={
        <MarkdownContent
          source={source}
          lexer={marked.lexer}
          headingOffset={1}
          labels={{
            table: en ? 'Reference table' : 'Bảng tham khảo',
            diagram: en ? 'Workflow' : 'Quy trình',
            source: en ? 'View source' : 'Xem nguồn',
            loading: en ? 'Loading diagram…' : 'Đang tải sơ đồ…',
            error: en ? 'The diagram could not be shown.' : 'Chưa hiển thị được sơ đồ.',
          }}
        />
      }
    />
  )
}
